B.Wi=new A.a5("\u042f \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u0434\u0440\u0443\u0433\u0443\u044e \u0444\u043e\u0440\u043c\u0443 \u2014 \u043f\u043e\u0447\u0435\u043c\u0443 \u043d\u0435 \u043e\u0448\u0438\u0431\u043a\u0430?","\xabBr\xfcder\xbb \u0432\u043c\u0435\u0441\u0442\u043e \xabBruder\xbb \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0441\u043b\u043e\u0432\u043e \u0432\u044b \u0432\u0441\u043f\u043e\u043c\u043d\u0438\u043b\u0438; \u043f\u0440\u043e\u043c\u0430\u0445 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0444\u043e\u0440\u043c\u0435. \u0422\u0430\u043a\u043e\u0439 \u043e\u0442\u0432\u0435\u0442 \u0438\u0434\u0451\u0442 \u043a\u0430\u043a \xab\u0442\u0440\u0443\u0434\u043d\u043e\xbb \u0438 \u0441\u043b\u0435\u0433\u043a\u0430 \u0443\u043a\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b, \u043d\u043e \u043f\u0440\u043e\u0432\u0430\u043b\u043e\u043c \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f.")
B.Wa=new A.a5("\u042f \u0432\u043f\u0438\u0441\u0430\u043b \u0441\u0438\u043d\u043e\u043d\u0438\u043c, \u0438 \u043e\u043d \u0442\u043e\u0436\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442","\u0415\u0441\u043b\u0438 \u044d\u0442\u043e \u0441\u043b\u043e\u0432\u043e \u2014 \u0442\u043e\u0436\u0435 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u043a\u043e\u043b\u043e\u0434\u044b \u0441 \u0442\u0435\u043c \u0436\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c, \u043e\u0442\u0432\u0435\u0442 \u0438\u0434\u0451\u0442 \u043a\u0430\u043a \xab\u0442\u0440\u0443\u0434\u043d\u043e\xbb \u0441 \u043f\u043e\u044f\u0441\u043d\u0435\u043d\u0438\u0435\u043c, \u0430 \u043d\u0435 \u043a\u0430\u043a \u043e\u0448\u0438\u0431\u043a\u0430. \u0420\u0430\u043c\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0440\u0430\u0437\u0434\u0435\u043b\u044f\u0435\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0437\u0430\u043c\u0435\u043d\u044f\u0435\u043c\u0443\u044e \u043f\u0430\u0440\u0443, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442.\n\n\u0415\u0441\u043b\u0438 \u0436\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0432\u0441\u0451-\u0442\u0430\u043a\u0438 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043b\u043e \u043f\u0440\u043e\u043c\u0430\u0445, \u0430 \u0432\u0430\u0448\u0435 \u0441\u043b\u043e\u0432\u043e \u0432 \u043f\u0440\u043e\u043f\u0443\u0441\u043a \u0432\u0441\u0442\u0430\u0451\u0442 \u2014 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041c\u043e\u0451 \u0441\u043b\u043e\u0432\u043e \u0442\u043e\u0436\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442\xbb. \u042d\u0442\u0430 \u0441\u0442\u0440\u043e\u043a\u0430 \u0436\u0443\u0440\u043d\u0430\u043b\u0430 \u043f\u043e\u043c\u0435\u0442\u0438\u0442\u0441\u044f \u0441\u043f\u043e\u0440\u043d\u043e\u0439 \u0438 \u043d\u0435 \u043f\u043e\u0439\u0434\u0451\u0442 \u0432 \u043f\u043e\u0434\u0433\u043e\u043d\u043a\u0443 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430.")
B.VM=new A.a5("\u0423 \u043c\u0435\u043d\u044f \u043d\u0435\u0442 \u043d\u0435\u043c\u0435\u0446\u043a\u043e\u0439 \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044b","\u0423\u043c\u043b\u0430\u0443\u0442\u044b \u043c\u043e\u0436\u043d\u043e \u043f\u0438\u0441\u0430\u0442\u044c \u0442\u0430\u043a \u0436\u0435, \u043a\u0430\u043a \u043f\u0438\u0448\u0435\u0442 \u0441\u0430\u043c \u043d\u0435\u043c\u0435\u0446\u043a\u0438\u0439 \u0431\u0435\u0437 \u043d\u0438\u0445: ae, oe, ue \u0438 ss. \xabfuer\xbb \u0437\u0430\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \xabf\xfcr\xbb, \xabStrasse\xbb \u2014 \u043a\u0430\u043a \xabStra\xdfe\xbb. \u041f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u044b\u0435 \u0442\u043e\u0447\u043a\u0438 \u2014 \xabfur\xbb \u2014 \u0438\u0434\u0443\u0442 \u043a\u0430\u043a \u043e\u043f\u0435\u0447\u0430\u0442\u043a\u0430, \u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0435 \u043d\u0435 \u0434\u0440\u0443\u0433\u043e\u0435 \u0441\u043b\u043e\u0432\u043e: \xabschon\xbb \u0432\u043c\u0435\u0441\u0442\u043e \xabsch\xf6n\xbb \u2014 \u043e\u0448\u0438\u0431\u043a\u0430.")
B.W2=new A.a5("\u042f \u0437\u0430\u0431\u044b\u043b \u043f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0443","\u0412\u0432\u043e\u0434 \u043a\u0438\u0440\u0438\u043b\u043b\u0438\u0446\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0438\u0441\u043a\u043e\u043c\u043e\u0435 \u0441\u043b\u043e\u0432\u043e, \u043d\u0435 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0432 \u0436\u0443\u0440\u043d\u0430\u043b \u0432\u043e\u043e\u0431\u0449\u0435: \u044d\u0442\u043e \u043d\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438, \u0430 \u043f\u0440\u043e\u043c\u0430\u0445 \u043f\u043e \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0435. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0441\u043f\u0440\u043e\u0441\u0438\u0442 \u0435\u0449\u0451 \u0440\u0430\u0437.")
B.W0=new A.a5("\u0413\u0434\u0435 \u043a\u043d\u043e\u043f\u043a\u0430 \xab\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u043e\u0442\u0432\u0435\u0442\xbb?","\u0415\u0451 \u043d\u0435\u0442 \u043d\u0438 \u043d\u0430 \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0443\u043f\u0435\u043d\u0438: \u0443\u0432\u0438\u0434\u0435\u0442\u044c \u043e\u0442\u0432\u0435\u0442 \u0434\u043e \u043f\u043e\u043f\u044b\u0442\u043a\u0438 \u2014 \u0437\u043d\u0430\u0447\u0438\u0442 \u043d\u0435 \u0432\u0441\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u0435\u0433\u043e. \u041f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u043c\u0430\u0445\u0430 \u0434\u0430\u0451\u0442\u0441\u044f \u0437\u0430\u0446\u0435\u043f\u043a\u0430 \u0438 \u0432\u0442\u043e\u0440\u0430\u044f \u043f\u043e\u043f\u044b\u0442\u043a\u0430; \u0443\u0441\u043f\u0435\u0445 \u0441\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u043f\u043e\u043f\u044b\u0442\u043a\u0438 \u0441\u0442\u043e\u0438\u0442 \xab\u0442\u0440\u0443\u0434\u043d\u043e\xbb.\n\n\u041d\u0430 \u0441\u0442\u0443\u043f\u0435\u043d\u0438 \u0441 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u043e\u0439 \u0440\u0443\u0441\u0441\u043a\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0441\u043f\u0440\u044f\u0442\u0430\u043d\u043e \u0437\u0430 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 \u2014 \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u0435\u0433\u043e \u043c\u043e\u0436\u043d\u043e, \u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u044d\u0442\u043e \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u043c\u0430\u0445: \u0441\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c \u043d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u0441\u0442\u0443\u043f\u0435\u043d\u044c \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442 \u043f\u0435\u0440\u0435\u0432\u043e\u0434, \u0430 \u043d\u0435 \u043f\u0440\u0438\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435.")
